'use strict';
window.OrthodoxTimeline=(()=>{
  let cached,pending;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normal=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const safe=value=>{try{const url=new URL(value);return /^https?:$/.test(url.protocol)?esc(url.href):'#';}catch{return '#';}};
  const external=(url,label)=>`<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
  const paragraphs=text=>String(text||'').split(/\n\s*\n/).map(part=>`<p>${esc(part).replace(/\n/g,'<br>')}</p>`).join('');
  const eras=[{id:'early',title:'Early Church',range:'30–799',from:30,to:799},{id:'medieval',title:'Medieval',range:'800–1499',from:800,to:1499},{id:'reformation',title:'Reformations',range:'1500–1599',from:1500,to:1599},{id:'confessions',title:'Confessions and churches',range:'1600–1749',from:1600,to:1749},{id:'modern',title:'Modern movements',range:'1750–present',from:1750,to:2100}];
  const topics={'authority':'Authority','trinity-christology':'Trinity and Christ','salvation':'Salvation','sacraments':'Sacraments','worship':'Worship and icons','scripture-tradition':'Scripture and Tradition','church-order':'Church organization'};
  const contexts={shared:'Early Church',orthodox:'Eastern Orthodox history',western:'Western / Roman Catholic history',protestant:'Protestant history'};
  const statuses={affirmed:'Affirmed',rejected:'Rejected',qualified:'Qualified',varies:'Varies by tradition','not-established':'Not established here'};
  const relationLabels={continuity:'Continuity',separation:'Separation',emergence:'Emergence',influence:'Influence'};
  async function load(){if(cached)return cached;if(pending)return pending;pending=Promise.all(['timeline.json','timeline-reception.json'].map(name=>(window.OrthodoxResources?window.OrthodoxResources.json('content/'+name).then(value=>({ok:true,json:async()=>value})):fetch('content/'+name)).then(response=>{if(!response.ok)throw new Error('History readings or reception notes could not be loaded.');return response.json();}))).then(([history,reception])=>{if(!Array.isArray(history.events)||!Array.isArray(history.sources)||!Array.isArray(reception.annotations))throw new Error('History data is incomplete.');const annotations=new Map(reception.annotations.map(item=>[item.eventId,item]));if(history.events.some(event=>!annotations.has(event.id)))throw new Error('Some historical entries have no reception classification.');const sources=new Map(history.sources.map(s=>[s.id,s]));for(const s of reception.sources||[])if(!sources.has(s.id))sources.set(s.id,s);cached={...history,sources:[...sources.values()],events:history.events.map(event=>({...event,reception:annotations.get(event.id)}))};return cached;}).catch(error=>{pending=null;throw error;});return pending;}
  function bibliography(s){const edition=String(s.edition||''),translator=String(s.translator||'');const label=/original|^(English (edition|online|translator)|Spoken|Official|Not identified|Historic|Translation reproduced)/i.test(translator)?translator:'Translation: '+translator;return [s.author,s.work||s.title,translator&&!normal(edition).includes(normal(translator))?label:'',edition,s.year&&!edition.includes(String(s.year))?s.year:''].filter(Boolean).join(' · ');}
  function rights(s){return `${s.attribution?`<p>${esc(s.attribution)}</p>`:''}${s.rights?`<p>${s.rightsUrl?external(s.rightsUrl,s.rights):esc(s.rights)}</p>`:''}${s.rightsNote?`<p>${esc(s.rightsNote)}</p>`:''}`;}
  async function mount(root,params){
    if(!root)return;root.innerHTML='<p role="status">Loading history…</p>';
    let data;try{data=await load();}catch(error){if(root.isConnected)root.innerHTML=`<div class="error-panel"><h1>History unavailable</h1><p>${esc(error.message)}</p><button class="secondary" data-tl-retry>Retry</button></div>`;root.querySelector('[data-tl-retry]')?.addEventListener('click',()=>mount(root,params));return;}
    if(!root.isConnected)return;
    const sourceMap=new Map(data.sources.map(s=>[s.id,s])),eventMap=new Map(data.events.map(e=>[e.id,e])),branchMap=new Map((data.branches||[]).map(b=>[b.id,b]));
    const state={view:['chronology','branches','book'].includes(params.get('view'))?params.get('view'):'chronology',era:eras.some(e=>e.id===params.get('era'))?params.get('era'):'all',topic:topics[params.get('topic')]?params.get('topic'):'',focus:params.get('focus')==='reformed'?'reformed':'all',all:params.get('detail')==='all',context:Object.hasOwn(contexts,params.get('context'))?params.get('context'):'',kind:['doctrinal','historical'].includes(params.get('kind'))?params.get('kind'):'',query:params.get('q')||'',event:params.get('event')||'',branch:branchMap.has(params.get('branch'))?params.get('branch'):null};
    let activeCard=null,drawFrame,citationNumbers=new Map();
    function setCitations(ids){citationNumbers=new Map([...new Set(ids.filter(id=>sourceMap.has(id)))].map((id,i)=>[id,i+1]));}
    function replaceRoute(){if(!root.isConnected||!(window.OrthodoxSite?.route()||location.hash).startsWith('#/timeline'))return;const query=new URLSearchParams();if(state.view!=='chronology')query.set('view',state.view);if(state.era!=='all')query.set('era',state.era);if(state.topic)query.set('topic',state.topic);if(state.focus!=='all')query.set('focus',state.focus);if(state.all)query.set('detail','all');if(state.context)query.set('context',state.context);if(state.kind)query.set('kind',state.kind);if(state.query)query.set('q',state.query);if(state.event)query.set('event',state.event);if(state.branch)query.set('branch',state.branch);history.replaceState(null,'','#/timeline'+(query.size?'?'+query.toString():''));}
    function references(ids){const unique=[...new Set(ids.filter(id=>sourceMap.has(id)))];return `<section class="tl-sources"><h2>Sources</h2><ol class="sources-list">${unique.map(id=>{const source=sourceMap.get(id);return `<li id="tl-source-${esc(id)}" data-scripture-source="${esc(id)}" tabindex="-1">${external(source.url,source.title)}<br>${esc(bibliography(source))}<div class="rights-metadata">${rights(source)}</div></li>`;}).join('')}</ol></section>`;}
    function cite(ids){return [...new Set((ids||[]).filter(id=>sourceMap.has(id)))].map(id=>`<a class="tl-citation" href="#tl-source-${esc(id)}" data-tl-source="${esc(id)}" aria-label="Read source: ${esc(sourceMap.get(id).title)}">[${citationNumbers.get(id)||"source"}]</a>`).join(' ');}
    function notesFor(event){return (data.book?.notes||[]).filter(note=>(note.eventIds||[]).includes(event.id));}
    function reading(item){const source=sourceMap.get(item.sourceId);if(!source)return '';return `<section class="tl-reading" data-scripture-source="${esc(item.sourceId)}"><h3>${esc(item.title||source.title)}</h3>${item.kind==='quotation'?`<blockquote class="quoted-reading" data-tl-quote="${esc(source.id)}">${paragraphs(item.text)}</blockquote>`:item.kind==='summary'?`<div>${paragraphs(item.text)}</div>`:''}<p class="reading-locator">${esc(item.locator||'')} ${cite([source.id])}</p><p>${external(item.url||source.url,item.kind==='link'?'Open full reading':'Read source')}</p>${source.attribution?`<p class="required-attribution">${esc(source.attribution)}</p>`:''}</section>`;}
    function bookNote(note){return `<section class="tl-book-note"><h3>${esc(note.title)}</h3><p class="tl-source-type">${esc({'book-excerpt':'Book excerpt','author-talk':'Author’s published talk or interview','publisher-description':'Publisher material'}[note.sourceType]||'Published author material')}${note.locator?' · '+esc(note.locator):''}</p>${note.kind==='quotation'?`<blockquote class="quoted-reading" data-tl-quote="${esc(note.sourceId||note.sourceIds?.[0])}">${paragraphs(note.text)}</blockquote>`:`<div>${paragraphs(note.text)}</div>`}<p>${cite(note.sourceIds||[note.sourceId])}</p>${(note.eventIds||[]).filter(id=>eventMap.has(id)).length?`<div class="tl-related">${note.eventIds.filter(id=>eventMap.has(id)).map(id=>`<button class="text-button" aria-haspopup="dialog" data-tl-event="${esc(id)}">${esc(eventMap.get(id).dateLabel)} · ${esc(eventMap.get(id).title)}</button>`).join('')}</div>`:''}</section>`;}

    function receptionRows(event,expanded=false){
      const record=event.reception;
      if(record.kind==='historical')return `<div class="tl-historical-note"><strong>Historical event</strong><p>${esc(record.scope)}</p></div>`;
      const positions=record.positions||[];
      if(!expanded)return `<section class="tl-card-reception" aria-label="Reception of the selected teaching"><h4>Who affirms this?</h4><p class="tl-compared"><strong>Teaching compared:</strong> ${esc(record.subject)}</p><p class="tl-reception-scope">${esc(record.scope)}</p><ul class="tl-position-list">${positions.map(position=>`<li><span>${esc(position.group)}</span><strong class="tl-status tl-status-${esc(position.status)}">${esc(position.label||statuses[position.status])}</strong></li>`).join('')}</ul><button class="text-button small" aria-label="Read positions and sources: ${esc(event.title)}" aria-haspopup="dialog" data-tl-event="${esc(event.id)}">Read positions and sources</button></section>`;
      return `<section class="tl-reception-detail"><h3>Who affirms this?</h3><p><strong>Teaching compared:</strong> ${esc(record.subject)}</p><p>${esc(record.scope)}</p><div class="tl-position-details">${positions.map(position=>`<section class="tl-position-detail"><header><h4>${esc(position.group)}</h4><strong class="tl-status tl-status-${esc(position.status)}">${esc(position.label||statuses[position.status])}</strong></header><p>${esc(position.text)} ${cite(position.sourceIds)}</p>${position.locators?.length?`<p class="tl-position-locator">${position.locators.map(esc).join(' · ')}</p>`:''}</section>`).join('')}</div>${(record.notes||[]).map(note=>`<p class="tl-reception-note">${esc(note.text)} ${cite(note.sourceIds)}</p>`).join('')}</section>`;
    }
    function card(event){
      const record=event.reception,doctrinal=record.kind==='doctrinal';
      return `<article class="tl-entry tl-context-${esc(event.lane)}" data-tl-id="${esc(event.id)}"><div class="tl-entry-date">${esc(event.dateLabel)}</div><div class="tl-entry-content"><header class="tl-entry-header"><div class="tl-entry-labels"><span class="tl-context-label">Context: ${esc(contexts[event.lane])}</span><span class="tl-kind-label">${doctrinal?'Teaching / ruling':'Historical event'}</span></div><h3><button class="tl-event-title" aria-haspopup="dialog" data-tl-event="${esc(event.id)}">${esc(event.title)}</button></h3></header><div class="tl-entry-body ${doctrinal?'tl-has-reception':''}"><div class="tl-entry-overview"><p>${esc(event.overview.text)}</p>${event.rulingLabel?`<p class="tl-entry-text"><strong>Text:</strong> ${esc(event.rulingLabel)}</p>`:''}${!doctrinal?`<p class="tl-history-scope">${esc(record.scope)}</p>`:''}<button class="text-button" aria-label="Read details and sources: ${esc(event.title)}" aria-haspopup="dialog" data-tl-event="${esc(event.id)}">${doctrinal?'Read ruling and sources':'Read event and sources'}</button>${notesFor(event).length?'<span class="tl-author-marker">Trenham note</span>':''}</div>${doctrinal?receptionRows(event):''}</div></div></article>`;
    }

    function matches(event){if(state.context&&event.lane!==state.context)return false;if(state.kind&&event.reception.kind!==state.kind)return false;const era=eras.find(e=>e.id===state.era);if(era&&!(event.year<=era.to&&(event.endYear||event.year)>=era.from))return false;if(!state.all&&!event.key)return false;if(state.topic&&!(event.topics||[]).includes(state.topic))return false;if(state.focus==='reformed'&&!(event.lane==='shared'||event.reformedContext||(event.traditions||[]).includes('reformed')))return false;const query=normal(state.query).trim().split(/\s+/).filter(Boolean),text=normal([event.title,event.dateLabel,event.rulingLabel,event.overview.text,event.reception.subject,...(event.reception.positions||[]).flatMap(p=>[p.group,p.label,p.text]),...(event.traditions||[]),...(event.readings||[]).map(r=>r.text||r.title)].join(' '));return query.every(term=>text.includes(term));}

    function chronology(){
      const shown=data.events.filter(matches).sort((a,b)=>a.year-b.year||a.title.localeCompare(b.title)),result=root.querySelector('#tl-results');
      root.querySelector('#tl-count').textContent=`${shown.length} of ${data.events.length} events`;
      if(!shown.length){result.innerHTML='<div class="empty"><h2>No events match</h2><p>Change a filter or show all events.</p><button class="secondary" data-tl-reset>Reset filters</button></div>';return;}
      result.innerHTML=eras.filter(era=>state.era==='all'||state.era===era.id).map(era=>{
        const events=shown.filter(e=>state.era==='all'?(e.year>=era.from&&e.year<=era.to):(e.year<=era.to&&(e.endYear||e.year)>=era.from));
        if(!events.length)return '';
        return `<section class="tl-era" id="tl-era-${era.id}" aria-labelledby="tl-era-title-${era.id}"><header><h2 id="tl-era-title-${era.id}">${era.title}</h2><span>${era.range}</span></header>${era.id==='early'?'<p class="tl-era-explanation">Early Christian history precedes the later divisions. Reception labels below identify agreement or disagreement about each selected teaching.</p>':''}<div class="tl-event-list">${events.map(card).join('')}</div></section>`;
      }).join('');
    }

    function detail(event){const noteList=notesFor(event),ids=[...(event.overview.sourceIds||[]),...(event.readings||[]).map(r=>r.sourceId),...(event.developments||[]).flatMap(d=>d.sourceIds||[]),...noteList.flatMap(n=>n.sourceIds||[n.sourceId]),...(event.reception.positions||[]).flatMap(p=>p.sourceIds||[]),...(event.reception.notes||[]).flatMap(n=>n.sourceIds||[])];setCitations(ids);return `<header class="tl-dialog-header"><div><p>${esc(event.dateLabel)} · ${esc(contexts[event.lane])} · ${event.reception.kind==='doctrinal'?'Teaching / ruling':'Historical event'}</p><h2 id="tl-dialog-title">${esc(event.title)}</h2></div><button class="secondary small" data-tl-close autofocus>Close</button></header><div class="tl-dialog-body"><section><h3>Event</h3><p>${esc(event.overview.text)} ${cite(event.overview.sourceIds)}</p>${event.rulingLabel?`<p><strong>Text:</strong> ${esc(event.rulingLabel)}</p>`:''}</section>${receptionRows(event,true)}${(event.readings||[]).map(reading).join('')}${event.developments?.length?`<section class="tl-developments"><h3>Subsequent developments</h3><ul>${event.developments.map(d=>`<li>${esc(d.text)} ${cite(d.sourceIds)}</li>`).join('')}</ul></section>`:''}${noteList.length?`<section class="tl-assessment"><h2>Trenham’s assessment</h2>${noteList.map(bookNote).join('')}</section>`:''}${event.relatedEventIds?.some(id=>eventMap.has(id))?`<section class="tl-related"><h3>Related events</h3>${event.relatedEventIds.filter(id=>eventMap.has(id)).map(id=>`<button class="text-button" aria-haspopup="dialog" data-tl-event="${esc(id)}">${esc(eventMap.get(id).dateLabel)} · ${esc(eventMap.get(id).title)}</button>`).join('')}</section>`:''}${event.lessonIds?.length?`<section class="tl-related"><h3>Curriculum</h3>${event.lessonIds.map(id=>`<a href="#/lesson/${encodeURIComponent(id)}">${esc(data.lessonTitles?.[id]||id)}</a>`).join('')}</section>`:''}${references(ids)}</div>`;}
    function openEvent(id,trigger){const event=eventMap.get(id);if(!event)return;if(trigger&&!trigger.closest('dialog'))activeCard=trigger;state.event=id;replaceRoute();const dialog=root.querySelector('#tl-dialog');dialog.dataset.tlId=event.id;dialog.innerHTML=detail(event);if(!dialog.open)dialog.showModal();else dialog.querySelector('[data-tl-close]').focus();dialog.scrollTop=0;}
    function closeEvent(){const dialog=root.querySelector('#tl-dialog');if(dialog.open)dialog.close();}
    function graphRanks(){const rank=new Map();const structural=(data.connections||[]).filter(c=>c.kind!=='influence');function depth(id,seen=new Set()){if(rank.has(id))return rank.get(id);if(seen.has(id))return 0;const next=new Set(seen);next.add(id);let parents=structural.filter(c=>c.to===id&&branchMap.has(c.from));if(!parents.length)parents=(data.connections||[]).filter(c=>c.to===id&&branchMap.has(c.from)&&c.from!==id&&(branchMap.get(id).kind==='teacher'||(branchMap.get(c.from).year||0)<=(branchMap.get(id).year||0)));const value=parents.length?Math.min(9,1+Math.max(...parents.map(c=>depth(c.from,next)))):0;rank.set(id,value);return value;}for(const id of branchMap.keys())depth(id);return rank;}
    function branchDetails(id){const node=branchMap.get(id),target=root.querySelector('#tl-branch-detail');if(!node){target.innerHTML='<p>Select a tradition, institution, or teacher for its documented connections.</p>';return;}const edges=(data.connections||[]).filter(c=>c.from===id||c.to===id),sources=[...(node.sourceIds||[]),...edges.flatMap(e=>e.sourceIds||[])];setCitations(sources);target.innerHTML=`<h2>${esc(node.label)}</h2><p>${esc(node.dateLabel||'')} · ${esc(node.kind)}</p>${node.eventId&&eventMap.has(node.eventId)?`<button class="secondary small" aria-haspopup="dialog" data-tl-event="${esc(node.eventId)}">Open timeline event</button>`:''}<ul class="tl-connections">${edges.map(edge=>{const other=branchMap.get(edge.from===id?edge.to:edge.from);return `<li><span class="tl-relationship">${esc(relationLabels[edge.kind]||edge.kind)}</span><strong>${esc(branchMap.get(edge.from)?.label)} / ${esc(branchMap.get(edge.to)?.label)}</strong><p>${esc(edge.label)} ${cite(edge.sourceIds)}</p>${other?`<button class="text-button" data-tl-branch="${esc(other.id)}">${esc(other.label)}</button>`:''}</li>`;}).join('')}</ul>${references(sources)}`;}

    function selectionTrace(){
      const nodes=new Set(),edges=new Set();if(!state.branch)return {nodes,edges};
      const queue=[state.branch];nodes.add(state.branch);
      while(queue.length){const id=queue.shift();for(const edge of data.connections||[]){if(edge.to!==id)continue;edges.add(edge.id);if(!nodes.has(edge.from)){nodes.add(edge.from);queue.push(edge.from);}}}
      return {nodes,edges};
    }
    function updateBranchSelection(){
      const trace=selectionTrace();root.querySelectorAll('.tl-branch-node').forEach(el=>{const selected=el.dataset.tlBranch===state.branch,predecessor=!selected&&trace.nodes.has(el.dataset.tlBranch);el.classList.toggle('is-selected',selected);el.classList.toggle('is-predecessor',predecessor);el.setAttribute('aria-pressed',String(selected));});
      const status=root.querySelector('#tl-branch-status');if(status)status.textContent=state.branch?`${branchMap.get(state.branch)?.label}: ${trace.nodes.size-1} connected predecessors highlighted.`:'Select a card to highlight its connected predecessors.';
    }
    function drawGraph(){
      const canvas=root.querySelector('.tl-graph-canvas'),svg=root.querySelector('.tl-graph-lines');if(!canvas||!svg)return;
      const box=canvas.getBoundingClientRect(),width=canvas.scrollWidth,height=canvas.scrollHeight,trace=selectionTrace();
      svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);
      svg.innerHTML='<defs><marker id="tl-tip" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6"/></marker><marker id="tl-tip-traced" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6"/></marker></defs>'+(data.connections||[]).map(edge=>{
        const from=[...canvas.querySelectorAll('[data-tl-branch]')].find(el=>el.dataset.tlBranch===edge.from),to=[...canvas.querySelectorAll('[data-tl-branch]')].find(el=>el.dataset.tlBranch===edge.to);if(!from||!to)return '';
        const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),x1=a.right-box.left,y1=a.top+a.height/2-box.top,x2=b.left-box.left,y2=b.top+b.height/2-box.top,bend=Math.max(35,Math.abs(x2-x1)*.45),active=trace.edges.has(edge.id);
        return `<path data-tl-edge="${esc(edge.id)}" class="${edge.kind==='influence'?'is-influence':''} ${active?'is-ancestor-path':''}" d="M${x1} ${y1} C${x1+bend} ${y1},${x2-bend} ${y2},${x2} ${y2}" marker-end="url(#${active?'tl-tip-traced':'tl-tip'})"><title>${esc(edge.label)}</title></path>`;
      }).join('');
    }
    function enableGraphDrag(){
      const viewport=root.querySelector('.tl-graph-scroll');if(!viewport)return;
      let gesture=null,suppressClick=false;
      viewport.addEventListener('pointerdown',event=>{if(!event.isPrimary||event.button!==0)return;gesture={id:event.pointerId,x:event.clientX,y:event.clientY,left:viewport.scrollLeft,dragging:false};});
      viewport.addEventListener('pointermove',event=>{if(!gesture||event.pointerId!==gesture.id)return;const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;if(!gesture.dragging&&Math.abs(dx)>6&&Math.abs(dx)>Math.abs(dy)){gesture.dragging=true;viewport.setPointerCapture(event.pointerId);viewport.classList.add('is-dragging');}if(gesture.dragging){event.preventDefault();viewport.scrollLeft=gesture.left-dx;}},{passive:false});
      const end=event=>{if(!gesture||event.pointerId!==gesture.id)return;if(gesture.dragging){suppressClick=true;setTimeout(()=>{suppressClick=false;},0);}if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId);gesture=null;viewport.classList.remove('is-dragging');};
      viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);
      viewport.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopImmediatePropagation();}},true);
      viewport.addEventListener('keydown',event=>{if(event.target!==viewport)return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();viewport.scrollBy({left:event.key==='ArrowRight'?180:-180});}else if(event.key==='Home'||event.key==='End'){event.preventDefault();viewport.scrollLeft=event.key==='Home'?0:viewport.scrollWidth;}});
    }
    function branches(){
      const ranks=graphRanks(),groups=[...new Set(ranks.values())].sort((a,b)=>a-b);root.querySelector('#tl-count').textContent=`${branchMap.size} traditions, institutions, and teachers`;
      root.querySelector('#tl-results').innerHTML=`<p class="tl-model-note">Historical relationships; this diagram does not rate doctrinal agreement. Solid lines: continuity, emergence, or separation. Dashed lines: influence.</p><div class="tl-graph-key"><span class="tl-key-selected">Selected card</span><span class="tl-key-predecessor">Connected predecessors and paths</span><span>Drag left or right. Keyboard: focus the diagram and use ← / →.</span></div><p id="tl-branch-status" class="tl-model-note" role="status"></p><div class="tl-graph-scroll" tabindex="0" aria-label="Historical relationships diagram; drag horizontally or use left and right arrow keys"><div class="tl-graph-canvas"><svg class="tl-graph-lines" aria-hidden="true"></svg><div class="tl-graph-columns">${groups.map(rank=>`<div class="tl-graph-column">${[...branchMap.values()].filter(node=>ranks.get(node.id)===rank).sort((a,b)=>(a.year||0)-(b.year||0)).map(node=>`<button class="tl-branch-node" data-tl-branch="${esc(node.id)}" aria-pressed="false"><strong>${esc(node.label)}</strong><span>${esc(node.dateLabel||'')}</span><small>${esc(node.kind)}</small></button>`).join('')}</div>`).join('')}</div></div></div><section id="tl-branch-detail" class="tl-branch-detail" aria-live="polite"></section>`;
      updateBranchSelection();enableGraphDrag();branchDetails(state.branch);requestAnimationFrame(drawGraph);
    }
    function book(){const notes=data.book?.notes||[];setCitations(data.book?.sources||notes.flatMap(n=>n.sourceIds||[n.sourceId]));root.querySelector('#tl-count').textContent=`${notes.length} source-bounded author notes`;root.querySelector('#tl-results').innerHTML=`<section class="tl-book"><h2>${esc(data.book?.title||'Rock and Sand')}</h2><p>${esc(data.book?.author||'Fr. Josiah Trenham')}</p><div class="notice"><strong>Verified source coverage</strong><p>${esc(data.book?.verifiedCoverage||'Only the author material identified below has been used.')}</p></div>${notes.map(bookNote).join('')}${references(data.book?.sources||notes.flatMap(n=>n.sourceIds||[n.sourceId]))}</section>`;}
    function renderResults(){root.querySelectorAll('[data-tl-view]').forEach(button=>{const active=button.dataset.tlView===state.view;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});root.querySelector('#tl-filters').hidden=state.view!=='chronology';if(state.view==='branches')branches();else if(state.view==='book')book();else chronology();replaceRoute();}

    root.innerHTML=`<div class="page-heading"><h1>Church History Timeline</h1></div><div class="tl-view-switch" role="group" aria-label="History view"><button class="chip" data-tl-view="chronology">Timeline</button><button class="chip" data-tl-view="branches">Branches</button><button class="chip" data-tl-view="book">Rock and Sand</button></div><section id="tl-filters" class="tl-filters" aria-label="Timeline filters"><div class="tl-reading-key"><p><strong>Historical context</strong> identifies the history being described. <strong>Who affirms this?</strong> compares the specific teaching named on each card, with sources in its details.</p><p>Agreement with a teaching does not necessarily mean acceptance of the council’s authority or every canon. “Not established here” means the cited sources do not settle that group’s position.</p></div><div class="tl-era-nav" role="group" aria-label="Historical era"><button data-tl-era="all" aria-pressed="${state.era==='all'}" class="chip ${state.era==='all'?'active':''}">All eras</button>${eras.map(e=>`<button class="chip ${state.era===e.id?'active':''}" data-tl-era="${e.id}" aria-pressed="${state.era===e.id}">${e.title}<small>${e.range}</small></button>`).join('')}</div><details class="tl-filter-options" ${state.context||state.kind||state.topic||state.focus!=='all'||state.query?'open':''}><summary>Search and filter</summary><div class="tl-filter-grid"><label>Historical context<select id="tl-context"><option value="">All contexts</option>${Object.entries(contexts).map(([id,label])=>`<option value="${id}" ${state.context===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Record type<select id="tl-kind"><option value="">All records</option><option value="doctrinal" ${state.kind==='doctrinal'?'selected':''}>Teachings / rulings</option><option value="historical" ${state.kind==='historical'?'selected':''}>Historical events</option></select></label><label>Topic<select id="tl-topic"><option value="">All topics</option>${Object.entries(topics).map(([id,label])=>`<option value="${id}" ${state.topic===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Focus<select id="tl-focus"><option value="all">All movements</option><option value="reformed" ${state.focus==='reformed'?'selected':''}>Reformed and related context</option></select></label><label class="tl-search-label">Search history and positions<input id="tl-query" type="search" class="search-input" value="${esc(state.query)}" placeholder="Council, teaching, church, or date"></label></div></details><div class="tl-filter-actions"><label class="tl-all-label"><input id="tl-all" type="checkbox" ${state.all?'checked':''}>Show all events</label><button class="text-button" data-tl-reset>Reset filters</button><span>Chronological order; spacing is not proportional to years.</span></div></section><p id="tl-count" class="result-count" role="status"></p><div id="tl-results"></div><dialog id="tl-dialog" class="tl-dialog" aria-labelledby="tl-dialog-title"></dialog>`;
    root.addEventListener('click',event=>{const button=event.target.closest('button,a');if(!button)return;
      if(button.dataset.tlSource){event.preventDefault();const scope=button.closest('dialog')||root;const target=scope.querySelector('#tl-source-'+CSS.escape(button.dataset.tlSource));target?.scrollIntoView({behavior:'smooth',block:'start'});target?.focus({preventScroll:true});}
      if(button.dataset.tlEvent){event.preventDefault();openEvent(button.dataset.tlEvent,button);}
      if(button.hasAttribute('data-tl-close'))closeEvent();
      if(button.dataset.tlView){closeEvent();state.view=button.dataset.tlView;state.event='';renderResults();}
      if(button.hasAttribute('data-tl-era')){state.era=button.dataset.tlEra;root.querySelectorAll('[data-tl-era]').forEach(el=>{const active=el.dataset.tlEra===state.era;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});renderResults();}
      if(button.hasAttribute('data-tl-reset')){state.era='all';state.context='';state.kind='';root.querySelector('#tl-context').value='';root.querySelector('#tl-kind').value='';state.topic='';state.focus='all';state.all=false;state.query='';root.querySelector('#tl-topic').value='';root.querySelector('#tl-focus').value='all';root.querySelector('#tl-all').checked=false;root.querySelector('#tl-query').value='';root.querySelectorAll('[data-tl-era]').forEach(el=>{const active=el.dataset.tlEra==='all';el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});renderResults();}
      if(button.dataset.tlBranch){state.branch=button.dataset.tlBranch;updateBranchSelection();branchDetails(state.branch);replaceRoute();drawGraph();}
    });
    root.addEventListener('change',event=>{if(event.target.id==='tl-context')state.context=event.target.value;else if(event.target.id==='tl-kind')state.kind=event.target.value;else if(event.target.id==='tl-topic')state.topic=event.target.value;else if(event.target.id==='tl-focus')state.focus=event.target.value;else if(event.target.id==='tl-all')state.all=event.target.checked;else return;renderResults();});
    root.querySelector('#tl-query').addEventListener('input',event=>{state.query=event.target.value;renderResults();});
    root.querySelector('#tl-dialog').addEventListener('close',()=>{if(!root.isConnected)return;state.event='';replaceRoute();if(activeCard?.isConnected)activeCard.focus({preventScroll:true});});
    if(window.ResizeObserver){const observer=new ResizeObserver(()=>{if(!root.isConnected){observer.disconnect();return;}cancelAnimationFrame(drawFrame);drawFrame=requestAnimationFrame(drawGraph);});observer.observe(root);}
    renderResults();if(state.event){const requested=state.event;if(eventMap.has(requested))openEvent(requested);else{state.event='';replaceRoute();root.querySelector('#tl-count').textContent+=' · Event link not found.';}}
  }
  return {load,mount};
})();
